export interface ConnectorConfig {
  linearApiKey: string
  linearTriageTeamId: string
  githubWebhookSecret: string
  fetch?: typeof fetch
}

export interface GitHubIssuePayload {
  action: string
  issue: {
    title: string
    body: string | null
    labels: Array<{ id: number; name: string; color: string; default: boolean; description: string | null }>
    user: { login: string }
    html_url: string
  }
  repository: { full_name: string }
  sender: { login: string }
}

export interface HandleResult {
  linearIssueId: string
  linearIssueTitle: string
}

function validatePayload(payload: unknown): asserts payload is GitHubIssuePayload {
  if (!payload || typeof payload !== 'object') {
    throw new Error('Payload must be an object')
  }
  const p = payload as Record<string, unknown>
  if (p.action !== 'labeled') {
    throw new Error(`Expected action "labeled", got "${p.action}"`)
  }
  if (!p.issue || typeof p.issue !== 'object') {
    throw new Error('Missing issue object')
  }
  const issue = p.issue as Record<string, unknown>
  if (typeof issue.title !== 'string' || !issue.title.trim()) {
    throw new Error('Issue title is required')
  }
  if (!Array.isArray(issue.labels)) {
    throw new Error('Issue labels array is required')
  }
  const hasBugLabel = issue.labels.some(
    (label: unknown) => label && typeof label === 'object' && (label as Record<string, unknown>).name === 'bug'
  )
  if (!hasBugLabel) {
    throw new Error('Issue does not have the "bug" label')
  }
  if (!issue.user || typeof issue.user !== 'object' || typeof (issue.user as Record<string, unknown>).login !== 'string') {
    throw new Error('Issue user.login is required')
  }
  if (typeof issue.html_url !== 'string' || !issue.html_url.trim()) {
    throw new Error('Issue html_url is required')
  }
}

function buildDescription(issue: GitHubIssuePayload['issue']): string {
  const parts: string[] = []
  if (issue.body) {
    parts.push(issue.body)
  }
  parts.push(`---`)
  parts.push(`Reported by: @${issue.user.login}`)
  parts.push(`Original issue: ${issue.html_url}`)
  return parts.join('\n')
}

function buildGraphQLMutation(title: string, description: string, teamId: string): string {
  const escapedTitle = title.replace(/"/g, '\\"').replace(/\n/g, '\\n')
  const escapedDescription = description.replace(/"/g, '\\"').replace(/\n/g, '\\n')
  return `mutation IssueCreate { issueCreate(input: { title: "${escapedTitle}", description: "${escapedDescription}", teamId: "${teamId}" }) { success issue { id title } } }`
}

export async function handle(payload: unknown, config: ConnectorConfig): Promise<HandleResult> {
  validatePayload(payload)
  const githubPayload = payload as GitHubIssuePayload

  const description = buildDescription(githubPayload.issue)
  const query = buildGraphQLMutation(githubPayload.issue.title, description, config.linearTriageTeamId)

  const fetchImpl = config.fetch ?? fetch
  const response = await fetchImpl('https://api.linear.app/graphql', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${config.linearApiKey}`,
    },
    body: JSON.stringify({ query }),
  })

  if (!response.ok) {
    throw new Error(`Linear API error: ${response.status} ${response.statusText} at POST https://api.linear.app/graphql`)
  }

  const data = (await response.json()) as {
    data?: { issueCreate?: { success: boolean; issue?: { id: string; title: string } } }
    errors?: Array<{ message: string }>
  }

  if (data.errors?.length) {
    throw new Error(`Linear GraphQL errors: ${data.errors.map((e) => e.message).join(', ')}`)
  }

  const issueCreate = data.data?.issueCreate
  if (!issueCreate?.success || !issueCreate.issue?.id) {
    throw new Error('Linear issueCreate did not return a successful issue')
  }

  return {
    linearIssueId: issueCreate.issue.id,
    linearIssueTitle: issueCreate.issue.title,
  }
}

import { describe, it, expect, vi, beforeEach } from 'vitest'
import { handle, ConnectorConfig, GitHubIssuePayload } from './connector'
import {
  SOURCE_EXAMPLE,
  TARGET_ENDPOINTS,
  contractFetch,
  fakeFetch,
  jsonResponse,
  type RecordedCall,
} from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      linearApiKey: 'test-linear-key',
      linearTriageTeamId: '9cfb482a-81e3-4154-b5b9-2c805e70a02d',
      githubWebhookSecret: 'test-github-secret',
      fetch,
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as GitHubIssuePayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.linearIssueId).toBe('LIN-123')
    expect(result.linearIssueTitle).toBe('Fix login button alignment')
  })
})

describe('handle', () => {
  let baseConfig: ConnectorConfig
  let calls: RecordedCall[]

  beforeEach(() => {
    baseConfig = {
      linearApiKey: 'test-linear-key',
      linearTriageTeamId: '9cfb482a-81e3-4154-b5b9-2c805e70a02d',
      githubWebhookSecret: 'test-github-secret',
    }
    calls = []
  })

  function makeFetch(handler: (req: RecordedCall) => Response | Promise<Response>) {
    const { fetch, calls: recordedCalls } = fakeFetch(handler)
    calls.push(...recordedCalls)
    return fetch
  }

  it('creates a Linear issue on happy path with correct field mapping', async () => {
    const fetch = makeFetch((req) => {
      expect(req.method).toBe('POST')
      expect(req.url).toBe('https://api.linear.app/graphql')
      expect(req.headers.get('authorization')).toBe('Bearer test-linear-key')
      const body = req.json as { query: string }
      expect(body.query).toContain('title: "Fix login button alignment"')
      expect(body.query).toContain('description:')
      expect(body.query).toContain('Reported by: @developer123')
      expect(body.query).toContain('Original issue: https://github.com/org/repo/issues/42')
      expect(body.query).toContain('teamId: "9cfb482a-81e3-4154-b5b9-2c805e70a02d"')
      return jsonResponse(TARGET_ENDPOINTS[0].response)
    })

    const result = await handle(SOURCE_EXAMPLE as unknown as GitHubIssuePayload, { ...baseConfig, fetch })
    expect(result.linearIssueId).toBe('LIN-123')
    expect(result.linearIssueTitle).toBe('Fix login button alignment')
  })

  it('uses Bearer token authentication', async () => {
    const fetch = makeFetch((req) => {
      expect(req.headers.get('authorization')).toBe('Bearer test-linear-key')
      return jsonResponse(TARGET_ENDPOINTS[0].response)
    })

    await handle(SOURCE_EXAMPLE as unknown as GitHubIssuePayload, { ...baseConfig, fetch })
  })

  it('throws when action is not labeled', async () => {
    const payload = { ...SOURCE_EXAMPLE, action: 'opened' }
    await expect(handle(payload as unknown as GitHubIssuePayload, baseConfig)).rejects.toThrow(
      'Expected action "labeled", got "opened"'
    )
  })

  it('throws when bug label is missing', async () => {
    const payload = {
      ...SOURCE_EXAMPLE,
      issue: { ...SOURCE_EXAMPLE.issue, labels: [{ id: 1, name: 'feature', color: 'fff', default: false, description: null }] },
    }
    await expect(handle(payload as unknown as GitHubIssuePayload, baseConfig)).rejects.toThrow(
      'Issue does not have the "bug" label'
    )
  })

  it('throws when issue title is missing', async () => {
    const payload = { ...SOURCE_EXAMPLE, issue: { ...SOURCE_EXAMPLE.issue, title: '' } }
    await expect(handle(payload as unknown as GitHubIssuePayload, baseConfig)).rejects.toThrow('Issue title is required')
  })

  it('throws when issue user.login is missing', async () => {
    const payload = { ...SOURCE_EXAMPLE, issue: { ...SOURCE_EXAMPLE.issue, user: { login: '' } } }
    await expect(handle(payload as unknown as GitHubIssuePayload, baseConfig)).rejects.toThrow('Issue user.login is required')
  })

  it('throws when issue html_url is missing', async () => {
    const payload = { ...SOURCE_EXAMPLE, issue: { ...SOURCE_EXAMPLE.issue, html_url: '' } }
    await expect(handle(payload as unknown as GitHubIssuePayload, baseConfig)).rejects.toThrow('Issue html_url is required')
  })

  it('throws on non-2xx response from Linear', async () => {
    const fetch = makeFetch(() => jsonResponse({ error: 'Unauthorized' }, 401))
    await expect(handle(SOURCE_EXAMPLE as unknown as GitHubIssuePayload, { ...baseConfig, fetch })).rejects.toThrow(
      'Linear API error: 401 Unauthorized at POST https://api.linear.app/graphql'
    )
  })

  it('throws on GraphQL errors in response', async () => {
    const fetch = makeFetch(() =>
      jsonResponse({
        errors: [{ message: 'Team not found' }, { message: 'Invalid teamId' }],
      })
    )
    await expect(handle(SOURCE_EXAMPLE as unknown as GitHubIssuePayload, { ...baseConfig, fetch })).rejects.toThrow(
      'Linear GraphQL errors: Team not found, Invalid teamId'
    )
  })

  it('throws when issueCreate returns unsuccessful', async () => {
    const fetch = makeFetch(() =>
      jsonResponse({
        data: { issueCreate: { success: false, issue: null } },
      })
    )
    await expect(handle(SOURCE_EXAMPLE as unknown as GitHubIssuePayload, { ...baseConfig, fetch })).rejects.toThrow(
      'Linear issueCreate did not return a successful issue'
    )
  })

  it('includes GitHub issue body in description when present', async () => {
    const fetch = makeFetch((req) => {
      const body = req.json as { query: string }
      expect(body.query).toContain('The login button is misaligned on mobile screens. Needs CSS fix.')
      return jsonResponse(TARGET_ENDPOINTS[0].response)
    })
    await handle(SOURCE_EXAMPLE as unknown as GitHubIssuePayload, { ...baseConfig, fetch })
  })

  it('handles null issue body gracefully', async () => {
    const payload = { ...SOURCE_EXAMPLE, issue: { ...SOURCE_EXAMPLE.issue, body: null } }
    const fetch = makeFetch((req) => {
      const body = req.json as { query: string }
      expect(body.query).toContain('Reported by: @developer123')
      expect(body.query).toContain('Original issue: https://github.com/org/repo/issues/42')
      return jsonResponse(TARGET_ENDPOINTS[0].response)
    })
    await handle(payload as unknown as GitHubIssuePayload, { ...baseConfig, fetch })
  })
})

