/** Example payload of the source event, as documented. */
export const SOURCE_EXAMPLE = {
  "action": "labeled",
  "issue": {
    "title": "Fix login button alignment",
    "body": "The login button is misaligned on mobile screens. Needs CSS fix.",
    "labels": [
      {
