export interface GitHubIssuePayload {
  action: string
  issue: {
    title: string
    body: string | null
    labels: Array<{ id: number; name: string; color: string; default: boolean; description: string | null }>
    user: { login: string }
    html_url: string
  }
  repository: { full_name: string }
  sender: { login: string }
}

export interface HandleResult {
  linearIssueId: string
  linearIssueTitle: string
}

function validatePayload(payload: unknown): asserts payload is GitHubIssuePayload {
  if (!payload || typeof payload !== 'object') {
    throw new Error('Payload must be an object')
  }
  const p = payload as Record<string, unknown>
  if (p.action !== 'labeled') {
    throw new Error(`Expected action "labeled", got "${p.action}"`)
  }
  if (!p.issue || typeof p.issue !== 'object') {
    throw new Error('Missing issue object')
  }
  const issue = p.issue as Record<string, unknown>
  if (typeof issue.title !== 'string' || !issue.title.trim()) {
    throw new Error('Issue title is required')
  }
  if (!Array.isArray(issue.labels)) {
    throw new Error('Issue labels array is required')
  }
  const hasBugLabel = issue.labels.some(
    (label: unknown) => label && typeof label === 'object' && (label as Record<string, unknown>).name === 'bug'
  )
  if (!hasBugLabel) {
    throw new Error('Issue does not have the "bug" label')
  }
  if (!issue.user || typeof issue.user !== 'object' || typeof (issue.user as Record<string, unknown>).login !== 'string' || !(issue.user as Record<string, unknown>).login.trim()) {
    throw new Error('Issue user.login is required')
  }
  if (typeof issue.html_url !== 'string' || !issue.html_url.trim()) {
    throw new Error('Issue html_url is required')
  }
}

function buildDescription(issue: GitHubIssuePayload['issue']): string {
  const parts: string[] = []
  if (issue.body) {
    parts.push(issue.body)
  }
  parts.push(`---`)
  parts.push(`Reported by: @${issue.user.login}`)
  parts.push(`Original issue: ${issue.html_url}`)
  return parts.join('\n')
}

function buildGraphQLMutation(title: string, description: string, teamId: string): string {
  const escapedTitle = title.replace(/"/g, '\\"').replace(/\n/g, '\\n')
  const escapedDescription = description.replace(/"/g, '\\"').replace(/\n/g, '\\n')
  return `mutation IssueCreate { issueCreate(input: { title: "${escapedTitle}", description: "${escapedDescription}", teamId: "${teamId}" }) { success issue { id title } } }`
}

export async function handle(payload: unknown, config: ConnectorConfig): Promise<HandleResult> {
  validatePayload(payload)
  const githubPayload = payload as GitHubIssuePayload

  const description = buildDescription(githubPayload.issue)
  const query = buildGraphQLMutation(githubPayload.issue.title, description, config.linearTriageTeamId)

  const fetchImpl = config.fetch ?? fetch
  const response = await fetchImpl('https://api.linear.app/graphql', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${config.linearApiKey}`,
    },
    body: JSON.stringify({ query }),
  })

  if (!response.ok) {
    throw new Error(`Linear API error: ${response.status} ${response.statusText} at POST https://api.linear.app/graphql`)
  }

  const data = (await response.json()) as {
    data?: { issueCreate?: { success: boolean; issue?: { id: string; title: string } } }
    errors?: Array<{ message: string }>
  }

  if (data.errors?.length) {
    throw new Error(`Linear GraphQL errors: ${data.errors.map((e) => e.message).join(', ')}`)
  }

  const issueCreate = data.data?.issueCreate
  if (!issueCreate?.success || !issueCreate.issue?.id) {
    throw new Error('Linear issueCreate did not return a successful issue')
  }

  return {
    linearIssueId: issueCreate.issue.id,
    linearIssueTitle: issueCreate.issue.title,
  }
}

